    "summary": "Apple's 13 revenue rows for FY2022 come from its quarterly 10‑Q filings (which report cumulative year‑to‑date revenue) plus the annual 10‑K filing, all using the single XBRL concept RevenueFromContractWithCustomerExcludingAssessedTax. No amendments or duplicate concepts are present.",
    "claims": [
      {
        "text": "Apple FY2022 revenue rows total 13, all for concept RevenueFromContractWithCustomerExcludingAssessedTax, with 3 rows from 10‑K filings and 10 rows from 10‑Q filings.",
        "evidence": ["E-db2094", "E-16ee26"]
      },
      {
        "text": "No fiscal period has more than one distinct accession number; each period shows accession_count = 1.",
        "evidence": ["E-0d779b"]
      },
      {
        "text": "The 10‑Q rows include periods such as 2020-09-27 to 2021-03-27, 2020-09-27 to 2021-06-26, and 2020-09-27 to 2021-09-25, indicating year‑to‑date reporting.",
        "evidence": ["E-0d779b", "E-71274f"]
      }
    ],
    "inferences": [
      {
        "text": "Because 10‑Q filings report cumulative revenue, each quarter yields multiple rows (Q1, Q1+Q2, Q1+Q2+Q3), and the annual 10‑K adds one row, producing the observed 13 rows.",
        "basis": ["claims"]
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-23bf9a",
        "status": "refuted",
        "evidence": ["E-0d779b"],
        "why": "No period shows more than one accession number, so amendments/restatements do not create duplicate rows for the same fiscal period."
      },
      {
        "id": "H-6472ba",
        "status": "refuted",
        "evidence": ["E-db2094", "E-0d779b"],
        "why": "Quarterly plus annual rows would be 5 per concept, but we have 13 rows; also no amendments exist to increase the count."
      },
      {
        "id": "H-54ac2e",
        "status": "refuted",
        "evidence": ["E-db2094", "E-16ee26"],
        "why": "All rows share the same concept and filing type; there is no dimensional column indicating separate segment rows."
      }
    ]
  },
  "carryover": {
    "COMPLETED": "H-23bf9a refuted; H-6472ba refuted; H-54ac2e refuted; H-1418d9 previously refuted.",
